{
  "root": "main_stack",
  "state": {
    "neighborhoods": [
      {
        "name": "Azabu-Juban (Minato)",
        "description": "International feel, very safe, and extremely quiet at night. Excellent local playgrounds and bakeries."
      },
      {
        "name": "Kichijoji (Musashino)",
        "description": "Consistently voted the most desirable place to live. Home to Inokashira Park and a very relaxed, kid-friendly vibe."
      }
    ],
    "itinerary": [
      {
        "dayRange": "Day 1-2",
        "time": "Morning",
        "activity": "Ghibli Museum (Kichijoji)",
        "details": "Magical world for children and adults.",
        "cost": "¥2,000",
        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Ghibli_Museum_Totoro.jpg/1200px-Ghibli_Museum_Totoro.jpg",
        "imageAlt": "Ghibli Museum Totoro"
      },
      {
        "dayRange": "Day 1-2",
        "time": "Afternoon",
        "activity": "Inokashira Park",
        "details": "Swan boat rentals and a small zoo.",
