        "image": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Ghibli_Museum_Totoro.jpg/1200px-Ghibli_Museum_Totoro.jpg",
        "imageAlt": "Ghibli Museum Totoro"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "page_title",
        "intro_text",
        "divider_1",
        "neighborhoods_section_title",
        "neighborhoods_table",
        "divider_2",
        "itinerary_section_title",
        "itinerary_table"
      ]
    },
    "page_title": {
      "type": "Text",
      "props": {
        "text": "Tokyo Family Trip Guide",
        "variant": "h1"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "Planning a family trip to Tokyo? Here's a guide to help you find kid-friendly neighborhoods and activities."
      },
      "children": []
    },
    "divider_1": {
      "type": "Divider",
      "props": {},
      "children": []
    },
    "neighborhoods_section_title": {
      "type": "Text",
      "props": {
        "text": "Family-Friendly Neighborhoods",
        "variant": "h2"
      },
      "children": []
    },
    "neighborhoods_table": {
      "type": "Table",
      "props": {
        "statePath": "/neighborhoods",
        "domain": "comparison",
        "preferredPresentation": "cards",
