        "text": "Sample Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "activity",
        "highlightColumns": [
          "time",
          "cost"
